import java.util.Objects;

final class IntArrayFormatter {
    private static final char VALUE_SEPARATOR = ' ';

    private IntArrayFormatter() {
    }

    static String format(int[] numbers) {
        Objects.requireNonNull(numbers, "numbers");

        if (numbers.length == 0) {
            return "";
        }

        StringBuilder output = new StringBuilder();
        for (int number : numbers) {
            output.append(number).append(VALUE_SEPARATOR);
        }

        return output.toString();
    }
}

import java.io.PrintStream;
import java.util.Objects;

final class BubbleSortDemo {
    private static final int[] SAMPLE_NUMBERS = {64, 34, 25, 12, 22, 11, 90};
    private static final String SORTED_ARRAY_LABEL = "Sorted array: ";

    private BubbleSortDemo() {
    }

    static void run(PrintStream output) {
        run(output, SAMPLE_NUMBERS);
    }

    static void run(PrintStream output, int[] numbers) {
        Objects.requireNonNull(output, "output");

        int[] sortedNumbers = BubbleSort.sortedCopy(numbers);

        output.println(SORTED_ARRAY_LABEL);
        output.println(IntArrayFormatter.format(sortedNumbers));
    }
}

import java.io.ByteArrayOutputStream;
import java.io.PrintStream;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;

final class BubbleSortTest {
    private BubbleSortTest() {
    }

    public static void main(String[] args) {
        runTest("sorts values in place", BubbleSortTest::sortsValuesInPlace);
        runTest("creates sorted copies", BubbleSortTest::createsSortedCopies);
        runTest("rejects null inputs", BubbleSortTest::rejectsNullInputs);
        runTest("formats arrays with original spacing", BubbleSortTest::formatsArraysWithOriginalSpacing);
        runTest("prints demo output", BubbleSortTest::printsDemoOutput);
        runTest("prints custom demo output", BubbleSortTest::printsCustomDemoOutput);

        System.out.println("All tests passed.");
    }

    private static void runTest(String testName, Runnable test) {
        try {
            test.run();
        } catch (AssertionError error) {
            throw new AssertionError("Test failed: " + testName, error);
        }
    }

    private static void sortsValuesInPlace() {
        for (SortCase sortCase : sortCases()) {
            int[] numbers = sortCase.input.clone();

            BubbleSort.sort(numbers);

            assertArrayEquals(sortCase.expected, numbers);
        }
    }

    private static void createsSortedCopies() {
        int[] numbers = {4, 2, 3};

        int[] sortedNumbers = BubbleSort.sortedCopy(numbers);

        assertArrayEquals(new int[] {2, 3, 4}, sortedNumbers);
        assertArrayEquals(new int[] {4, 2, 3}, numbers);
    }

    private static void rejectsNullInputs() {
        assertThrows(NullPointerException.class, () -> BubbleSort.sort(null));
        assertThrows(NullPointerException.class, () -> BubbleSort.sortedCopy(null));
        assertThrows(NullPointerException.class, () -> IntArrayFormatter.format(null));
        assertThrows(NullPointerException.class, () -> BubbleSortDemo.run(null));
        assertThrows(
                NullPointerException.class,
                () -> BubbleSortDemo.run(testPrintStream(new ByteArrayOutputStream()), null));
    }

    private static void formatsArraysWithOriginalSpacing() {
        assertEquals("3 4 5 ", IntArrayFormatter.format(new int[] {3, 4, 5}));
    }

    private static void printsDemoOutput() {
        String output = captureDemoOutput(BubbleSortDemo::run);

        assertEquals(expectedDemoOutput("11 12 22 25 34 64 90 "), output);
    }

    private static void printsCustomDemoOutput() {
        int[] numbers = {9, 2, 7};

        String output = captureDemoOutput(printStream -> BubbleSortDemo.run(printStream, numbers));

        assertEquals(expectedDemoOutput("2 7 9 "), output);
        assertArrayEquals(new int[] {9, 2, 7}, numbers);
    }

    private static String captureDemoOutput(DemoAction action) {
        ByteArrayOutputStream output = new ByteArrayOutputStream();
        action.run(testPrintStream(output));
        return output.toString(StandardCharsets.UTF_8);
    }

    private static PrintStream testPrintStream(ByteArrayOutputStream output) {
        return new PrintStream(output, true, StandardCharsets.UTF_8);
    }

    private static String expectedDemoOutput(String numbersLine) {
        return "Sorted array: "
                + System.lineSeparator()
                + numbersLine
                + System.lineSeparator();
    }

    private static void assertArrayEquals(int[] expected, int[] actual) {
        if (!Arrays.equals(expected, actual)) {
            throw new AssertionError(
                    "Expected " + Arrays.toString(expected) + " but got " + Arrays.toString(actual));
        }
    }

    private static void assertEquals(String expected, String actual) {
        if (!expected.equals(actual)) {
            throw new AssertionError("Expected \"" + expected + "\" but got \"" + actual + "\"");
        }
    }

    private static void assertThrows(Class<? extends RuntimeException> expectedType, Runnable action) {
        try {
            action.run();
        } catch (RuntimeException exception) {
            if (expectedType.isInstance(exception)) {
                return;
            }

            throw new AssertionError(
                    "Expected " + expectedType.getSimpleName() + " but got " + exception.getClass().getSimpleName(),
                    exception);
        }

        throw new AssertionError("Expected " + expectedType.getSimpleName());
    }

    private static SortCase[] sortCases() {
        return new SortCase[] {
                new SortCase(new int[] {64, 34, 25, 12, 22, 11, 90}, new int[] {11, 12, 22, 25, 34, 64, 90}),
                new SortCase(new int[] {1, 2, 3, 4}, new int[] {1, 2, 3, 4}),
                new SortCase(new int[] {5, 1, 5, 3, 1}, new int[] {1, 1, 3, 5, 5}),
                new SortCase(new int[] {}, new int[] {})
        };
    }

    private static final class SortCase {
        private final int[] input;
        private final int[] expected;

        private SortCase(int[] input, int[] expected) {
            this.input = input;
            this.expected = expected;
        }
    }

    private interface DemoAction {
        void run(PrintStream output);
    }
}
